const a = ($input.first().json.body) || $input.first().json;
const sevMap = { LOW: 1, MEDIUM: 2, HIGH: 3 };
const ports = Array.isArray(a.ports) ? a.ports.join(', ') : (a.ports || '');
// Observables: which IP the activity came from (src) and what it targeted (dst).
// One observable per distinct IP; src and dst can be the same (loopback test).
const roles = {};
for (const [role, ip] of [['src', a.src_ip], ['dst', a.dst_ip]]) {
  if (ip) (roles[ip] = roles[ip] || []).push(role);
}
const artifacts = Object.entries(roles).map(([ip, r]) => ({
  dataType: 'ip',
  data: ip,
  message: `${r.includes('src') ? 'Source' : 'Target'} of ${a.rule_id || 'IDS'} ${a.rule_name || 'activity'}`,
  tags: ['ids', a.rule_id, ...r.map(x => `ids:${x}`)].filter(Boolean)
}));
const payload = {
  type: 'ids',
  source: 'homelab-ids',
  sourceRef: `${a.rule_id || 'IDS'}-${a.timestamp || Date.now()}`,
  title: `${a.rule_id || ''} ${a.rule_name || 'IDS alert'}`.trim(),
  description: `Rule: ${a.rule_id} - ${a.rule_name}\nSeverity: ${a.severity}\nSource IP: ${a.src_ip || 'N/A'}\nDest IP: ${a.dst_ip || 'N/A'}\nPorts: ${ports}\nCount: ${a.count || 'N/A'}\nTime: ${a.timestamp || ''}`,
  severity: sevMap[a.severity] || 2,
  tags: ['ids', 'homelab', a.rule_id].filter(Boolean),
  artifacts
};
return [{ json: payload }];
